window.__SHB_EGYPTIAN_BOOK_QUESTIONS__=(window.__SHB_EGYPTIAN_BOOK_QUESTIONS__||[]).concat([{"id":"EB-paediatrics-cardiology-accepted-CH11-Q001","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Thepathologicalhallmarkoftheacuterheumatic fever","o":["Langerhancells","Reidsternbergcells","Aschoffnodules","Tuberculoma"],"ol":["A","B","C","D"],"k":2,"ex":"Aschoff nodules are characteristic histopathological lesions of rheumatic carditis. They are granulomatous inflammatory foci found in the myocardium and are classically associated with acute rheumatic fever.","more":"Aschoff nodules are characteristic histopathological lesions of rheumatic carditis. They are granulomatous inflammatory foci found in the myocardium and are classically associated with acute rheumatic fever.\n\nCurriculum alignment: CVS 2024 colored, pp.38–40: rheumatic fever pathophysiology and proliferative Aschoff nodules.\n\nHigh-yield point: Aschoff nodules are characteristic histopathological lesions of rheumatic carditis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q001 — Q1: Pathological hallmark of acute rheumatic fever","aoSource":"Question-bank MD page 139 · Printed page 261 · Answer-key PDF page 149 · Original question Q1","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q003","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Majorcriterionofacuterheumaticfever","o":["Arthalgia","Arthritis","SignificantASOtitre","hypotonia"],"ol":["A","B","C","D"],"k":1,"ex":"Arthritis (classically polyarthritis in low-risk populations) is a major Jones criterion for acute rheumatic fever. The revised Jones criteria vary by population risk: in moderate/high-risk populations monoarthritis and, in specified circumstances, polyarthralgia may also qualify as major. An elevated ASO titre is not itself a major criterion; it is evidence of preceding group A streptococcal infection.","more":"Arthritis (classically polyarthritis in low-risk populations) is a major Jones criterion for acute rheumatic fever. The revised Jones criteria vary by population risk: in moderate/high-risk populations monoarthritis and, in specified circumstances, polyarthralgia may also qualify as major. An elevated ASO titre is not itself a major criterion; it is evidence of preceding group A streptococcal infection.\n\nCurriculum alignment: CVS 2024 colored, pp.38–39: modified Jones criteria. Current CDC guidance (6 Aug 2025) retains population-risk-dependent Jones criteria: https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/diagnosing-acute-rheumatic-fever.html.\n\nHigh-yield point: Arthritis (classically polyarthritis in low-risk populations) is a major Jones criterion for acute rheumatic fever.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q003 — Q3: Major criterion of acute rheumatic fever","aoSource":"Question-bank MD page 139 · Printed page 261 · Answer-key PDF page 149 · Original question Q3","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q004","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Thevalveswhich aremostcommonlyinvolved in rheumaticfever","o":["Mitral,aortic","Mitral,tricuspid","Aortic,tricuspid","Aortic,pulmonary"],"ol":["A","B","C","D"],"k":0,"ex":"Rheumatic valvulitis predominantly affects the mitral valve, followed by the aortic valve. Tricuspid involvement is less common and pulmonary valve disease is rare. Acute rheumatic carditis may cause mitral regurgitation; chronic scarring may produce mitral stenosis and sometimes aortic valve disease.","more":"Rheumatic valvulitis predominantly affects the mitral valve, followed by the aortic valve. Tricuspid involvement is less common and pulmonary valve disease is rare. Acute rheumatic carditis may cause mitral regurgitation; chronic scarring may produce mitral stenosis and sometimes aortic valve disease.\n\nCurriculum alignment: CVS 2024 colored, pp.39–41: acute and chronic rheumatic valvular disease.\n\nHigh-yield point: Rheumatic valvulitis predominantly affects the mitral valve, followed by the aortic valve.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q004 — Q4: Valves most commonly involved in rheumatic fever","aoSource":"Question-bank MD page 139 · Printed page 261 · Answer-key PDF page 149 · Original question Q4","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q006","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Themurmurdenotesactivecarditis","o":["CareyCoombsmurmur","Mid-diastolicmurmur","Pansystolicmurmur","Machinarymurmur"],"ol":["A","B","C","D"],"k":0,"ex":"The Carey Coombs murmur is a short apical mid-diastolic murmur caused by increased flow across an inflamed, edematous mitral valve during acute rheumatic carditis. It is an auscultatory clue to active mitral valvulitis, not chronic fixed mitral stenosis.","more":"The Carey Coombs murmur is a short apical mid-diastolic murmur caused by increased flow across an inflamed, edematous mitral valve during acute rheumatic carditis. It is an auscultatory clue to active mitral valvulitis, not chronic fixed mitral stenosis.\n\nCurriculum alignment: CVS 2024 colored, pp.39–40: acute mitral regurgitation/stenosis, Carey Coombs murmur and rheumatic carditis.\n\nHigh-yield point: The Carey Coombs murmur is a short apical mid-diastolic murmur caused by increased flow across an inflamed, edematous mitral valve during acute rheumatic carditis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q006 — Q6: Murmur associated with active rheumatic carditis","aoSource":"Question-bank MD page 140 · Printed page 262 · Answer-key PDF page 149 · Original question Q6","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q008","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"TheCareyCoombsmurmurisdueto","o":["Inflammationofthemitralvalve","Increaseddiastolicflowacrossthemitralvalve","Both","None"],"ol":["A","B","C","D"],"k":1,"ex":"The Carey Coombs murmur is produced by increased diastolic blood flow across the mitral valve when the valve leaflets are inflamed and edematous during acute rheumatic carditis. The flow across the valve, rather than fixed chronic stenosis, generates the mid-diastolic murmur.","more":"The Carey Coombs murmur is produced by increased diastolic blood flow across the mitral valve when the valve leaflets are inflamed and edematous during acute rheumatic carditis. The flow across the valve, rather than fixed chronic stenosis, generates the mid-diastolic murmur.\n\nCurriculum alignment: CVS 2024 colored, p.40: Carey Coombs mid-diastolic murmur due to mitral valve edema/increased flow.\n\nHigh-yield point: The Carey Coombs murmur is produced by increased diastolic blood flow across the mitral valve when the valve leaflets are inflamed and edematous during acute rheumatic carditis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q008 — Q8: Mechanism producing the Carey Coombs murmur","aoSource":"Question-bank MD page 140 · Printed page 262 · Answer-key PDF page 149 · Original question Q8","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q011","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Clinical Features","q":"Thesiteofthesubcutaneousnodule,except","o":["Elbows","Occiput","Chest","Shin"],"ol":["A","B","C","D"],"k":2,"ex":"Rheumatic subcutaneous nodules are firm, painless nodules over bony prominences and extensor surfaces, such as elbows and knees. They may also be found over the occiput and vertebral spinous processes. The anterior chest is not a classic site in the listed description.","more":"Rheumatic subcutaneous nodules are firm, painless nodules over bony prominences and extensor surfaces, such as elbows and knees. They may also be found over the occiput and vertebral spinous processes. The anterior chest is not a classic site in the listed description.\n\nCurriculum alignment: CVS 2024 colored, p.40: subcutaneous nodules over bony prominences (elbow/knee) and extensor surfaces.\n\nHigh-yield point: Rheumatic subcutaneous nodules are firm, painless nodules over bony prominences and extensor surfaces, such as elbows and knees.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q011 — Q11: Site of rheumatic subcutaneous nodules: exception","aoSource":"Question-bank MD page 140 · Printed page 262 · Answer-key PDF page 149 · Original question Q11","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q015","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"MinorcriteriaofrheumaticfeverintheECGis,","o":["ProlongedP-Rinterval","Supraventriculartachycardia","ProlongedQ-Tinterval","Heartblock"],"ol":["A","B","C","D"],"k":0,"ex":"Prolonged PR interval (first-degree AV conduction delay) is a minor Jones criterion, provided carditis is not already counted as a major criterion. A prolonged PR interval is not interchangeable with any degree of heart block; the criterion refers specifically to PR prolongation after considering age-related norms.","more":"Prolonged PR interval (first-degree AV conduction delay) is a minor Jones criterion, provided carditis is not already counted as a major criterion. A prolonged PR interval is not interchangeable with any degree of heart block; the criterion refers specifically to PR prolongation after considering age-related norms.\n\nCurriculum alignment: CVS 2024 colored, pp.38–39: modified Jones criteria; CDC Jones criteria guidance, 6 Aug 2025, https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/diagnosing-acute-rheumatic-fever.html.\n\nHigh-yield point: Prolonged PR interval (first-degree AV conduction delay) is a minor Jones criterion, provided carditis is not already counted as a major criterion.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q015 — Q15: Minor ECG criterion in acute rheumatic fever","aoSource":"Question-bank MD page 140 · Printed page 262 · Answer-key PDF page 149 · Original question Q15","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q017","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Aspirinisgiveninrheumaticarthritisfor","o":["2weeks","4-6weeks","10weeks","12weeks"],"ol":["A","B","C","D"],"k":1,"ex":"The supplied lecture describes salicylate therapy for arthritis/mild carditis at an anti-inflammatory dose for about two weeks, followed by a lower dose for another 4–6 weeks. Therefore a total treatment period of approximately 6–8 weeks is consistent with the old course schedule, although current anti-inflammatory choice and duration are individualized according to symptoms and inflammatory activity.","more":"The supplied lecture describes salicylate therapy for arthritis/mild carditis at an anti-inflammatory dose for about two weeks, followed by a lower dose for another 4–6 weeks. Therefore a total treatment period of approximately 6–8 weeks is consistent with the old course schedule, although current anti-inflammatory choice and duration are individualized according to symptoms and inflammatory activity.\n\nCurriculum alignment: CVS 2024 colored, p.41: salicylates 100 mg/kg/day for two weeks then 5 mg/kg/day for 4–6 weeks. Extended Beyond Core Curriculum because exact anti-inflammatory regimens are historical/course-specific and are individualized in modern care.\n\nHigh-yield point: The supplied lecture describes salicylate therapy for arthritis/mild carditis at an anti-inflammatory dose for about two weeks, followed by a lower dose for another 4–6 weeks.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q017 — Q17: Duration of aspirin therapy for rheumatic arthritis","aoSource":"Question-bank MD page 141 · Printed page 263 · Answer-key PDF page 149 · Original question Q17","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q020","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Clinical Features","q":"Theearlysymptomsofthemitralregurgitation","o":["Fatigue","Palpitation","Dyspnea","Repeatedchestinfection"],"ol":["A","B","C","D"],"k":0,"ex":"Chronic mitral regurgitation may initially be asymptomatic. Early symptoms when they occur include reduced exercise tolerance and fatigue; exertional dyspnea and palpitations can develop as left atrial/left ventricular volume load and pulmonary venous pressure increase. The source key selects fatigue, a plausible early nonspecific symptom.","more":"Chronic mitral regurgitation may initially be asymptomatic. Early symptoms when they occur include reduced exercise tolerance and fatigue; exertional dyspnea and palpitations can develop as left atrial/left ventricular volume load and pulmonary venous pressure increase. The source key selects fatigue, a plausible early nonspecific symptom.\n\nCurriculum alignment: CVS 2024 colored, pp.39–41 and valve disease sections: rheumatic mitral valve disease and clinical effects.\n\nHigh-yield point: Chronic mitral regurgitation may initially be asymptomatic.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q020 — Q20: Early symptom of mitral regurgitation","aoSource":"Question-bank MD page 141 · Printed page 263 · Answer-key PDF page 149 · Original question Q20","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q021","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Leftventricularfailureusuallyoccursearlyinmitral regurgitationincasebecauseof","o":["Severelesion","LVmyocardialdysfunction","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Severe mitral regurgitation causes significant volume overload of the left atrium and left ventricle. When the regurgitant lesion is severe and/or myocardial contractility becomes impaired, left ventricular failure can develop. The source key “both” reflects both severe valve lesion and LV myocardial dysfunction as contributing factors.","more":"Severe mitral regurgitation causes significant volume overload of the left atrium and left ventricle. When the regurgitant lesion is severe and/or myocardial contractility becomes impaired, left ventricular failure can develop. The source key “both” reflects both severe valve lesion and LV myocardial dysfunction as contributing factors.\n\nCurriculum alignment: CVS 2024 colored, pp.39–41: rheumatic mitral disease and heart-failure mechanisms.\n\nHigh-yield point: Severe mitral regurgitation causes significant volume overload of the left atrium and left ventricle.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q021 — Q21: Early left ventricular failure in severe mitral regurgitation","aoSource":"Question-bank MD page 141 · Printed page 263 · Answer-key PDF page 149 · Original question Q21","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q022","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Clinical Features","q":"Theearlysymptomsofthemitralstenosis","o":["Dyspneaonexertion","Palpitation","Chestpain","Repeatedchestinfection"],"ol":["A","B","C","D"],"k":0,"ex":"Exertional dyspnea is a classic early symptom of mitral stenosis because the narrowed mitral valve raises left atrial pressure and pulmonary venous pressure, especially during exercise when diastolic filling time shortens. Palpitations may occur with atrial arrhythmias; chest pain and recurrent chest infection are less characteristic early symptoms.","more":"Exertional dyspnea is a classic early symptom of mitral stenosis because the narrowed mitral valve raises left atrial pressure and pulmonary venous pressure, especially during exercise when diastolic filling time shortens. Palpitations may occur with atrial arrhythmias; chest pain and recurrent chest infection are less characteristic early symptoms.\n\nCurriculum alignment: CVS 2024 colored, pp.39–41: mitral stenosis and its haemodynamic consequences.\n\nHigh-yield point: Exertional dyspnea is a classic early symptom of mitral stenosis because the narrowed mitral valve raises left atrial pressure and pulmonary venous pressure, especially during exercise when diastolic filling time shortens.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q022 — Q22: Early symptom of mitral stenosis","aoSource":"Question-bank MD page 141 · Printed page 263 · Answer-key PDF page 149 · Original question Q22","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q027","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Congenitalheartdiseasethatcanbecuredmedically is","o":["PDA","ASD","VSD","TOP"],"ol":["A","B","C","D"],"k":0,"ex":"Patent ductus arteriosus in selected preterm infants may close pharmacologically with cyclo-oxygenase inhibitors such as ibuprofen or indomethacin, which reduce prostaglandin synthesis. This is not generally a medical “cure” for every PDA: management depends on gestational age, hemodynamic significance and contraindications.","more":"Patent ductus arteriosus in selected preterm infants may close pharmacologically with cyclo-oxygenase inhibitors such as ibuprofen or indomethacin, which reduce prostaglandin synthesis. This is not generally a medical “cure” for every PDA: management depends on gestational age, hemodynamic significance and contraindications.\n\nCurriculum alignment: CVS 2024 colored, pp.14–15: PDA and medical closure in preterm infants; pp.8–9: VSD and natural history.\n\nHigh-yield point: Patent ductus arteriosus in selected preterm infants may close pharmacologically with cyclo-oxygenase inhibitors such as ibuprofen or indomethacin, which reduce prostaglandin synthesis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q027 — Q27: Congenital heart disease that may close with medical treatment","aoSource":"Question-bank MD page 142 · Printed page 264 · Answer-key PDF page 149 · Original question Q27","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q028","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pharmacology / Treatment","q":"Thedrugofchoiceinpatentductusartereosis","o":["Indomethacin","Propranalol","Frusemide","Digoxin"],"ol":["A","B","C","D"],"k":0,"ex":"Indomethacin inhibits cyclo-oxygenase and prostaglandin synthesis, promoting ductal constriction and closure in selected preterm infants with a hemodynamically significant PDA. Ibuprofen is also commonly used and may be preferred in some protocols; acetaminophen is another option in selected cases. The source-key answer is a traditional accepted treatment, but not a universal choice for all newborns.","more":"Indomethacin inhibits cyclo-oxygenase and prostaglandin synthesis, promoting ductal constriction and closure in selected preterm infants with a hemodynamically significant PDA. Ibuprofen is also commonly used and may be preferred in some protocols; acetaminophen is another option in selected cases. The source-key answer is a traditional accepted treatment, but not a universal choice for all newborns.\n\nCurriculum alignment: CVS 2024 colored, p.15: anti-prostaglandin treatment with indomethacin or ibuprofen in preterm PDA.\n\nHigh-yield point: Indomethacin inhibits cyclo-oxygenase and prostaglandin synthesis, promoting ductal constriction and closure in selected preterm infants with a hemodynamically significant PDA.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q028 — Q28: Drug of choice for patent ductus arteriosus closure","aoSource":"Question-bank MD page 142 · Printed page 264 · Answer-key PDF page 149 · Original question Q28","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q029","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Themurmurofatrialseptaldefectisproducedat","o":["Aorticvalve","Mitralvalve","Tricuspid","Pulmonaryvalve"],"ol":["A","B","C","D"],"k":3,"ex":"The characteristic ejection systolic murmur in ASD is not generated by blood crossing the atrial septal defect. It is caused by increased flow across the pulmonary valve into the pulmonary artery, producing a systolic flow murmur at the upper left sternal border. A fixed wide split S2 is another important finding.","more":"The characteristic ejection systolic murmur in ASD is not generated by blood crossing the atrial septal defect. It is caused by increased flow across the pulmonary valve into the pulmonary artery, producing a systolic flow murmur at the upper left sternal border. A fixed wide split S2 is another important finding.\n\nCurriculum alignment: CVS 2024 colored, pp.12–13: ASD clinical examination and increased pulmonary-valve flow.\n\nHigh-yield point: The characteristic ejection systolic murmur in ASD is not generated by blood crossing the atrial septal defect.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q029 — Q29: Site producing the murmur in atrial septal defect","aoSource":"Question-bank MD page 142 · Printed page 264 · Answer-key PDF page 149 · Original question Q29","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q032","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"HeartFailureinV.S.Ddoesnotpresentbefore8th weekofagebecause","o":["Highpulmonaryvascularresistance","Lowpulmonaryvascularresistance","Both","None"],"ol":["A","B","C","D"],"k":0,"ex":"At birth, pulmonary vascular resistance is relatively high, limiting left-to-right shunting through a VSD. As pulmonary vascular resistance falls over the first several weeks, pulmonary blood flow and left-to-right shunt volume increase; a large VSD may then cause pulmonary congestion, tachypnea, feeding difficulty and heart failure.","more":"At birth, pulmonary vascular resistance is relatively high, limiting left-to-right shunting through a VSD. As pulmonary vascular resistance falls over the first several weeks, pulmonary blood flow and left-to-right shunt volume increase; a large VSD may then cause pulmonary congestion, tachypnea, feeding difficulty and heart failure.\n\nCurriculum alignment: CVS 2024 colored, pp.8–10: VSD haemodynamics, high pulmonary vascular resistance at birth and later symptoms.\n\nHigh-yield point: At birth, pulmonary vascular resistance is relatively high, limiting left-to-right shunting through a VSD.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q032 — Q32: Why heart failure in VSD usually appears after several weeks","aoSource":"Question-bank MD page 142 · Printed page 264 · Answer-key PDF page 149 · Original question Q32","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q037","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Thedefectspresentintetralogyoffallot,except","o":["Pulmon.stenosis","VSD","RVH","LVH"],"ol":["A","B","C","D"],"k":3,"ex":"Tetralogy of Fallot consists of a large VSD, overriding aorta, right ventricular outflow obstruction (usually pulmonary stenosis) and right ventricular hypertrophy. Left ventricular hypertrophy is not one of the four defining components.","more":"Tetralogy of Fallot consists of a large VSD, overriding aorta, right ventricular outflow obstruction (usually pulmonary stenosis) and right ventricular hypertrophy. Left ventricular hypertrophy is not one of the four defining components.\n\nCurriculum alignment: CVS 2024 colored, pp.23–25: four components and physiology of tetralogy of Fallot.\n\nHigh-yield point: Tetralogy of Fallot consists of a large VSD, overriding aorta, right ventricular outflow obstruction (usually pulmonary stenosis) and right ventricular hypertrophy.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q037 — Q37: Component not present in tetralogy of Fallot","aoSource":"Question-bank MD page 143 · Printed page 265 · Answer-key PDF page 149 · Original question Q37","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q039","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Examination","q":"Thecardiovasculardiseasewhichcanbediagnosed bymerepalpation","o":["VSD","PDA","Coarctationofaorta","Carditis"],"ol":["A","B","C","D"],"k":2,"ex":"Coarctation of the aorta may be strongly suspected by palpating weak or delayed femoral pulses compared with upper-limb pulses (radiofemoral delay), often with upper-limb hypertension. Palpation raises suspicion; echocardiography and vascular imaging establish anatomy and severity.","more":"Coarctation of the aorta may be strongly suspected by palpating weak or delayed femoral pulses compared with upper-limb pulses (radiofemoral delay), often with upper-limb hypertension. Palpation raises suspicion; echocardiography and vascular imaging establish anatomy and severity.\n\nCurriculum alignment: CVS 2024 colored, pp.18–19: coarctation, weak femoral pulses and radiofemoral delay.\n\nHigh-yield point: Coarctation of the aorta may be strongly suspected by palpating weak or delayed femoral pulses compared with upper-limb pulses (radiofemoral delay), often with upper-limb hypertension.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q039 — Q39: Cardiovascular disease suggested by palpation alone","aoSource":"Question-bank MD page 143 · Printed page 265 · Answer-key PDF page 149 · Original question Q39","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q048","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thenoncardiaccausesofcongestivecardiacfailure, except","o":["Anemia","Thyrotoxicosis","Beriberi","Fluidoverload"],"ol":["A","B","C","D"],"k":3,"ex":"Anemia, thyrotoxicosis and thiamine deficiency (beriberi) can produce high-output cardiac failure through increased cardiac workload or impaired energy metabolism. Fluid overload can precipitate pulmonary/systemic congestion or decompensate existing heart failure, but is not conventionally grouped as a primary non-cardiac high-output cause in the same way. The source key d is the intended exception.","more":"Anemia, thyrotoxicosis and thiamine deficiency (beriberi) can produce high-output cardiac failure through increased cardiac workload or impaired energy metabolism. Fluid overload can precipitate pulmonary/systemic congestion or decompensate existing heart failure, but is not conventionally grouped as a primary non-cardiac high-output cause in the same way. The source key d is the intended exception.\n\nCurriculum alignment: CVS 2024 colored, heart-failure sections and differential diagnosis of cardiac failure; Growth/Nutrition content for nutritional deficiency overlap.\n\nHigh-yield point: Anemia, thyrotoxicosis and thiamine deficiency (beriberi) can produce high-output cardiac failure through increased cardiac workload or impaired energy metabolism.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q048 — Q48: Non-cardiac causes of congestive heart failure: exception","aoSource":"Question-bank MD page 143 · Printed page 265 · Answer-key PDF page 149 · Original question Q48","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q053","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Clinical Features","q":"Thepresenting symptomsofcongestivecardiac failureininfancy","o":["Feedingdifficulty","Failuretothrive","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Infants with heart failure commonly have feeding difficulty because feeding is exertion; they may become tachypneic, sweaty or fatigued during feeds. Chronic increased energy expenditure and poor intake can cause failure to thrive. Thus both listed symptoms are common presentations.","more":"Infants with heart failure commonly have feeding difficulty because feeding is exertion; they may become tachypneic, sweaty or fatigued during feeds. Chronic increased energy expenditure and poor intake can cause failure to thrive. Thus both listed symptoms are common presentations.\n\nCurriculum alignment: CVS 2024 colored, pp.8–10 and heart-failure section: feeding difficulty, poor weight gain and failure to thrive.\n\nHigh-yield point: Infants with heart failure commonly have feeding difficulty because feeding is exertion; they may become tachypneic, sweaty or fatigued during feeds.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q053 — Q53: Presenting symptoms of congestive heart failure in infancy","aoSource":"Question-bank MD page 143 · Printed page 265 · Answer-key PDF page 149 · Original question Q53","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q056","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Examination","q":"Thewideandfixedsplitsecondheartsoundoccurin","o":["Mitralstenosis","VSD","Atrialseptaldefect","Coarctationofaorta"],"ol":["A","B","C","D"],"k":2,"ex":"Atrial septal defect classically produces a wide, fixed split second heart sound. The right ventricular stroke volume remains increased throughout the respiratory cycle, so the split varies little with inspiration and expiration.","more":"Atrial septal defect classically produces a wide, fixed split second heart sound. The right ventricular stroke volume remains increased throughout the respiratory cycle, so the split varies little with inspiration and expiration.\n\nCurriculum alignment: CVS 2024 colored, pp.12–13: ASD examination and fixed wide split S2.\n\nHigh-yield point: Atrial septal defect classically produces a wide, fixed split second heart sound.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q056 — Q56: Wide and fixed splitting of the second heart sound","aoSource":"Question-bank MD page 143 · Printed page 265 · Answer-key PDF page 149 · Original question Q56","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q057","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Examination","q":"Paradoxicallysplitsecond heartsound signifies severe","o":["Pulmonarystenosis","Aorticstenosis","Mitralstenosis","Tricuspidstenosis"],"ol":["A","B","C","D"],"k":1,"ex":"Paradoxical (reversed) splitting of S2 occurs when aortic valve closure is delayed, as in severe aortic stenosis or left bundle branch block. In the listed options, severe aortic stenosis is the intended answer.","more":"Paradoxical (reversed) splitting of S2 occurs when aortic valve closure is delayed, as in severe aortic stenosis or left bundle branch block. In the listed options, severe aortic stenosis is the intended answer.\n\nCurriculum alignment: CVS 2024 colored, cardiac auscultation/murmur section; question extends standard physiology of S2 splitting.\n\nHigh-yield point: Paradoxical (reversed) splitting of S2 occurs when aortic valve closure is delayed, as in severe aortic stenosis or left bundle branch block.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q057 — Q57: Lesion associated with paradoxical splitting of the second heart sound","aoSource":"Question-bank MD page 144 · Printed page 266 · Answer-key PDF page 149 · Original question Q57","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q058","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"Thepulmonaryplethoraisseeninall,except","o":["VSD","TOF","ASD","PDA"],"ol":["A","B","C","D"],"k":1,"ex":"Pulmonary plethora occurs with left-to-right shunts such as VSD, ASD and PDA because pulmonary blood flow is increased. Tetralogy of Fallot has right ventricular outflow obstruction and reduced pulmonary blood flow, so the lung fields are classically oligemic rather than plethoric.","more":"Pulmonary plethora occurs with left-to-right shunts such as VSD, ASD and PDA because pulmonary blood flow is increased. Tetralogy of Fallot has right ventricular outflow obstruction and reduced pulmonary blood flow, so the lung fields are classically oligemic rather than plethoric.\n\nCurriculum alignment: CVS 2024 colored, pp.8–15 and 23–25: left-to-right shunts versus TOF lung blood flow.\n\nHigh-yield point: Pulmonary plethora occurs with left-to-right shunts such as VSD, ASD and PDA because pulmonary blood flow is increased.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q058 — Q58: Congenital heart disease not associated with pulmonary plethora","aoSource":"Question-bank MD page 144 · Printed page 266 · Answer-key PDF page 149 · Original question Q58","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q059","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"AllarecharacteristicofFallot's,except","o":["Infundibularstenosis","Overridingofaorta","VSD","Leftventricularfailure"],"ol":["A","B","C","D"],"k":3,"ex":"Tetralogy of Fallot consists of pulmonary stenosis/right ventricular outflow obstruction, VSD, overriding aorta and right ventricular hypertrophy. Left ventricular failure is not a defining characteristic of uncomplicated TOF; severe hypoxemia and cyanotic spells dominate the clinical picture.","more":"Tetralogy of Fallot consists of pulmonary stenosis/right ventricular outflow obstruction, VSD, overriding aorta and right ventricular hypertrophy. Left ventricular failure is not a defining characteristic of uncomplicated TOF; severe hypoxemia and cyanotic spells dominate the clinical picture.\n\nCurriculum alignment: CVS 2024 colored, pp.23–25: TOF components and clinical presentation.\n\nHigh-yield point: Tetralogy of Fallot consists of pulmonary stenosis/right ventricular outflow obstruction, VSD, overriding aorta and right ventricular hypertrophy.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q059 — Q59: Characteristic features of tetralogy of Fallot: exception","aoSource":"Question-bank MD page 144 · Printed page 266 · Answer-key PDF page 149 · Original question Q59","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q060","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Pharmacology","q":"Ininfants,extracardiacdigitalistoxicityismanifested by","o":["Vomiting","Convulsions","Blurringofvision","Rashes"],"ol":["A","B","C","D"],"k":0,"ex":"Digoxin toxicity commonly causes gastrointestinal symptoms, including anorexia, nausea, vomiting and diarrhea. Infants may present with feeding intolerance or vomiting rather than the visual color disturbances classically described in adults. Serious toxicity can also cause bradyarrhythmias or other dysrhythmias.","more":"Digoxin toxicity commonly causes gastrointestinal symptoms, including anorexia, nausea, vomiting and diarrhea. Infants may present with feeding intolerance or vomiting rather than the visual color disturbances classically described in adults. Serious toxicity can also cause bradyarrhythmias or other dysrhythmias.\n\nCurriculum alignment: CVS 2024 colored, pp.33–34: digitalis toxicity manifestations; GIT effects include anorexia, nausea, vomiting and diarrhea.\n\nHigh-yield point: Digoxin toxicity commonly causes gastrointestinal symptoms, including anorexia, nausea, vomiting and diarrhea.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q060 — Q60: Extracardiac manifestation of digoxin toxicity in infants","aoSource":"Question-bank MD page 144 · Printed page 266 · Answer-key PDF page 149 · Original question Q60","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q064","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Endocarditisisrareamongchildrenwith","o":["ASD","PDA","VSD","TOF"],"ol":["A","B","C","D"],"k":0,"ex":"An isolated secundum ASD has a very low risk of infective endocarditis and is not included among the classic high-risk congenital lesions for which routine antibiotic prophylaxis is indicated. VSD, PDA, cyanotic CHD such as TOF and certain repaired defects carry greater endocarditis risk depending on anatomy and repair status.","more":"An isolated secundum ASD has a very low risk of infective endocarditis and is not included among the classic high-risk congenital lesions for which routine antibiotic prophylaxis is indicated. VSD, PDA, cyanotic CHD such as TOF and certain repaired defects carry greater endocarditis risk depending on anatomy and repair status.\n\nCurriculum alignment: CVS 2024 colored, pp.13–15 and infective endocarditis section: isolated secundum ASD contrasted with other CHD.\n\nHigh-yield point: An isolated secundum ASD has a very low risk of infective endocarditis and is not included among the classic high-risk congenital lesions for which routine antibiotic prophylaxis is indicated.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q064 — Q64: Congenital heart disease with comparatively low infective endocarditis risk","aoSource":"Question-bank MD page 145 · Printed page 267 · Answer-key PDF page 149 · Original question Q64","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q068","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Examination","q":"Thefollowingisnotanormalfindinginthenewborn","o":["Systolicmurmur","Peripheralcyanosis","Pulserateof100/min","Centralcyanosis"],"ol":["A","B","C","D"],"k":3,"ex":"Central cyanosis is abnormal in a newborn and requires urgent assessment for hypoxemia, respiratory disease, congenital heart disease or other causes. Peripheral acrocyanosis can occur transiently in otherwise well newborns. Heart rate around 100/min can be within the newborn range depending on state, and a soft systolic murmur may be transitional but must be assessed clinically.","more":"Central cyanosis is abnormal in a newborn and requires urgent assessment for hypoxemia, respiratory disease, congenital heart disease or other causes. Peripheral acrocyanosis can occur transiently in otherwise well newborns. Heart rate around 100/min can be within the newborn range depending on state, and a soft systolic murmur may be transitional but must be assessed clinically.\n\nCurriculum alignment: CVS 2024 colored, newborn transition/CHD presentation; Neonatology 2024–2025, newborn examination and cyanosis.\n\nHigh-yield point: Central cyanosis is abnormal in a newborn and requires urgent assessment for hypoxemia, respiratory disease, congenital heart disease or other causes.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q068 — Q68: Abnormal finding in a newborn","aoSource":"Question-bank MD page 145 · Printed page 267 · Answer-key PDF page 149 · Original question Q68","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q074","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Complications","q":"ThedangerwiththepatientwithPDA","o":["Syncope","Arrhythmia","Convulsion","Bacterialendocarditis"],"ol":["A","B","C","D"],"k":3,"ex":"An unrepaired PDA can predispose to infective endarteritis/endocarditis, heart failure and pulmonary vascular disease depending on shunt size. Among the listed options, bacterial endocarditis is the intended infectious complication. Current care also considers hemodynamic effects and pulmonary hypertension, not endocarditis alone.","more":"An unrepaired PDA can predispose to infective endarteritis/endocarditis, heart failure and pulmonary vascular disease depending on shunt size. Among the listed options, bacterial endocarditis is the intended infectious complication. Current care also considers hemodynamic effects and pulmonary hypertension, not endocarditis alone.\n\nCurriculum alignment: CVS 2024 colored, pp.14–15: PDA and complications, including IE.\n\nHigh-yield point: An unrepaired PDA can predispose to infective endarteritis/endocarditis, heart failure and pulmonary vascular disease depending on shunt size.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q074 — Q74: Major danger associated with patent ductus arteriosus","aoSource":"Question-bank MD page 146 · Printed page 268 · Answer-key PDF page 149 · Original question Q74","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q076","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thefollowingisnotthecharacteristicoftheright- sidedfailure","o":["Pulmonaryedema","Oliguria","Ascitis","Dependantedema"],"ol":["A","B","C","D"],"k":0,"ex":"Right-sided heart failure causes systemic venous congestion: hepatomegaly, ascites, dependent peripheral edema and sometimes oliguria from reduced renal perfusion. Pulmonary edema is more characteristic of left-sided heart failure, although biventricular failure can produce both systemic and pulmonary congestion.","more":"Right-sided heart failure causes systemic venous congestion: hepatomegaly, ascites, dependent peripheral edema and sometimes oliguria from reduced renal perfusion. Pulmonary edema is more characteristic of left-sided heart failure, although biventricular failure can produce both systemic and pulmonary congestion.\n\nCurriculum alignment: CVS 2024 colored, heart-failure section: systemic versus pulmonary congestion.\n\nHigh-yield point: Right-sided heart failure causes systemic venous congestion: hepatomegaly, ascites, dependent peripheral edema and sometimes oliguria from reduced renal perfusion.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q076 — Q76: Finding not characteristic of right-sided heart failure","aoSource":"Question-bank MD page 146 · Printed page 268 · Answer-key PDF page 149 · Original question Q76","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q077","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thefollowingisofleastclinicalsignificance","o":["Singleatrium","Patentforamenovale","Ostiumprimum","Ostiumsecondum"],"ol":["A","B","C","D"],"k":-1,"ex":"A patent foramen ovale (PFO) is common and usually causes no clinical problem; most close functionally/anatomically during infancy, and treatment is rarely needed in otherwise healthy individuals. Ostium primum and ostium secundum are true atrial septal defects with potential hemodynamic consequences; “single atrium” is a major congenital anomaly. The source does not provide an answer key, so the most likely educational interpretation is option b, but this is not a source-provided answer.","more":"A patent foramen ovale (PFO) is common and usually causes no clinical problem; most close functionally/anatomically during infancy, and treatment is rarely needed in otherwise healthy individuals. Ostium primum and ostium secundum are true atrial septal defects with potential hemodynamic consequences; “single atrium” is a major congenital anomaly. The source does not provide an answer key, so the most likely educational interpretation is option b, but this is not a source-provided answer.\n\nCurriculum alignment: CVS 2024 colored, fetal circulation p.3 and ASD section pp.12–13; American Heart Association PFO summary: common, usually asymptomatic and no treatment in most people, https://www.heart.org/en/health-topics/congenital-heart-defects/about-congenital-heart-defects/patent-foramen-ovale-pfo.\n\nHigh-yield point: Source answer: Not Provided by Source. Editorial likely answer b is stated separately and must not be substituted for a missing source key.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":true,"aoTitle":"CH11-Q077 — Q77: Least clinically significant atrial septal communication","aoSource":"Question-bank MD page 146 · Printed page 268 · Answer-key PDF page Not provided · Original question Q77","aoSystem":"أمراض القلب","aoPart":"","kx":true,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q082","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Prognosis / Complications","q":"ThecourseofuntreatedVSDarefollowing,except","o":["Spontaneousclosure","Developmentofpulmonaryinsufficiency","Subacutebacterialendocarditis","Normallife"],"ol":["A","B","C","D"],"k":1,"ex":"Small VSDs, especially muscular defects, may close spontaneously. Persistent moderate/large defects can cause pulmonary overcirculation, heart failure, pulmonary vascular disease/Eisenmenger syndrome and infective endocarditis. Pulmonary insufficiency is not a typical defining natural-history outcome of an untreated VSD, making it the intended exception. “Normal life” may occur with a small defect, but is not guaranteed for all VSDs.","more":"Small VSDs, especially muscular defects, may close spontaneously. Persistent moderate/large defects can cause pulmonary overcirculation, heart failure, pulmonary vascular disease/Eisenmenger syndrome and infective endocarditis. Pulmonary insufficiency is not a typical defining natural-history outcome of an untreated VSD, making it the intended exception. “Normal life” may occur with a small defect, but is not guaranteed for all VSDs.\n\nCurriculum alignment: CVS 2024 colored, pp.8–11: VSD natural history and complications.\n\nHigh-yield point: Small VSDs, especially muscular defects, may close spontaneously.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q082 — Q82: Natural history of untreated VSD: exception","aoSource":"Question-bank MD page 146 · Printed page 268 · Answer-key PDF page 149 · Original question Q82","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q085","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Examination","q":"CareyCoombsMurmur'ofrheumaticfever","o":["Apicalpansystolicmurmur","Apicalearlydiastolicmurmur","Apicalmiddiastolicmurmur","Baselejectionsystolicmurmur"],"ol":["A","B","C","D"],"k":2,"ex":"Carey Coombs murmur is a short apical mid-diastolic murmur due to increased flow across an inflamed and edematous mitral valve during acute rheumatic carditis. It differs from the chronic mitral stenosis murmur caused by fixed commissural fusion.","more":"Carey Coombs murmur is a short apical mid-diastolic murmur due to increased flow across an inflamed and edematous mitral valve during acute rheumatic carditis. It differs from the chronic mitral stenosis murmur caused by fixed commissural fusion.\n\nCurriculum alignment: CVS 2024 colored, p.40: acute rheumatic mitral disease and Carey Coombs murmur.\n\nHigh-yield point: Carey Coombs murmur is a short apical mid-diastolic murmur due to increased flow across an inflamed and edematous mitral valve during acute rheumatic carditis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q085 — Q85: Auscultatory location and timing of Carey Coombs murmur","aoSource":"Question-bank MD page 147 · Printed page 269 · Answer-key PDF page 149 · Original question Q85","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q094","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Management","q":"Emergencytreatmentoftransposition ofgreat vessels","o":["Balloonatrialseptostomy","Ventilation","Oxygen","Digoxin"],"ol":["A","B","C","D"],"k":0,"ex":"In transposition of the great arteries, systemic and pulmonary circulations run in parallel. Survival depends on mixing through an atrial, ventricular or ductal communication. Balloon atrial septostomy (Rashkind procedure) enlarges a restrictive atrial communication and rapidly improves mixing in a critically cyanotic newborn. Prostaglandin E1 is also commonly used to maintain ductal patency while definitive repair is arranged, although it is not among the options.","more":"In transposition of the great arteries, systemic and pulmonary circulations run in parallel. Survival depends on mixing through an atrial, ventricular or ductal communication. Balloon atrial septostomy (Rashkind procedure) enlarges a restrictive atrial communication and rapidly improves mixing in a critically cyanotic newborn. Prostaglandin E1 is also commonly used to maintain ductal patency while definitive repair is arranged, although it is not among the options.\n\nCurriculum alignment: CVS 2024 colored, pp.26–30: TGA, mixing lesions and emergency management; emergency management concept extends PGE1 use.\n\nHigh-yield point: In transposition of the great arteries, systemic and pulmonary circulations run in parallel.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q094 — Q94: Emergency treatment of transposition of the great arteries","aoSource":"Question-bank MD page 147 · Printed page 269 · Answer-key PDF page 149 · Original question Q94","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q095","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Etiology","q":"Infantilemyocarditisandpericarditisisdueto","o":["CoxsackieA","Mumps","CoxsackieB","Poxvirus"],"ol":["A","B","C","D"],"k":2,"ex":"Coxsackie B enteroviruses are classically associated with myocarditis and pericarditis in infants and children. Other viruses can also cause myocarditis, but Coxsackie B is the traditional exam association.","more":"Coxsackie B enteroviruses are classically associated with myocarditis and pericarditis in infants and children. Other viruses can also cause myocarditis, but Coxsackie B is the traditional exam association.\n\nCurriculum alignment: CVS 2024 colored, myocarditis section pp.32–34.\n\nHigh-yield point: Coxsackie B enteroviruses are classically associated with myocarditis and pericarditis in infants and children.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q095 — Q95: Viral cause associated with infantile myocarditis and pericarditis","aoSource":"Question-bank MD page 147 · Printed page 269 · Answer-key PDF page 149 · Original question Q95","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-cardiology-accepted-CH11-Q096","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Management","q":"ThechildwithtetralogyofFallotusethefollowing position","o":["Supine","Squatting","Prone","Leaningforward"],"ol":["A","B","C","D"],"k":1,"ex":"A child with TOF may squat during a hypercyanotic (“tet”) spell. Squatting or the knee-chest position increases systemic vascular resistance, reducing right-to-left shunting and improving pulmonary blood flow and oxygenation. In infants, caregivers use the knee-chest position.","more":"A child with TOF may squat during a hypercyanotic (“tet”) spell. Squatting or the knee-chest position increases systemic vascular resistance, reducing right-to-left shunting and improving pulmonary blood flow and oxygenation. In infants, caregivers use the knee-chest position.\n\nCurriculum alignment: CVS 2024 colored, pp.24–25: tet spells and squatting/knee-chest position.\n\nHigh-yield point: A child with TOF may squat during a hypercyanotic (“tet”) spell.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH11-Q096 — Q96: Position adopted by a child with tetralogy of Fallot during a cyanotic spell","aoSource":"Question-bank MD page 147 · Printed page 269 · Answer-key PDF page 149 · Original question Q96","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Cardiology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q4","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Cardiology / heart failure supportive care","q":"Measuresinthetreatmentofcardiacfailureother thanmedicineexcept","o":["Bedrest","FluidIntake/outputchart","Highsaltdiet","Lowsaltdiet"],"ol":["A","B","C","D"],"k":2,"ex":"Supportive measures in paediatric heart failure may include rest or reduced exertion, careful fluid balance, daily weight, and sodium restriction when clinically indicated. A high-salt diet can worsen sodium and water retention and is therefore the exception.","more":"Supportive measures in paediatric heart failure may include rest or reduced exertion, careful fluid balance, daily weight, and sodium restriction when clinically indicated. A high-salt diet can worsen sodium and water retention and is therefore the exception. **Why the others are wrong:** (a) Bed rest/reduced activity: may reduce cardiac workload in decompensated failure. (b) Intake/output chart: tracks fluid balance. (c) High-salt diet: incorrect; may worsen fluid retention. (d) Low-salt diet: may be used to reduce sodium retention, individualized to age and condition.\n\nCurriculum alignment: CVS 2024, heart failure section: non-pharmacological measures, fluid/salt balance and monitoring. **High-yield point / Review Notes:** Salt and fluid restriction in children must be individualized; avoid compromising growth or nutrition.\n\nHigh-yield point: Supportive measures in paediatric heart failure may include rest or reduced exertion, careful fluid balance, daily weight, and sodium restriction when clinically indicated.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q4 — Cardiology / heart failure supportive care","aoSource":"Question-bank MD p.155 · printed p.305 · answer-key PDF p.168 · original Q4","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q68","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Cardiology / pulse pressure","q":"Widepulsepressureisseeninthefollowing,except","o":["PDA","Anaemia","AR","ASD"],"ol":["A","B","C","D"],"k":3,"ex":"Wide pulse pressure occurs when systolic pressure is relatively high and/or diastolic pressure is low. A patent ductus arteriosus and aortic regurgitation can cause a wide pulse pressure; severe anaemia can produce a hyperdynamic circulation. An isolated atrial septal defect does not classically cause wide pulse pressure.","more":"Wide pulse pressure occurs when systolic pressure is relatively high and/or diastolic pressure is low. A patent ductus arteriosus and aortic regurgitation can cause a wide pulse pressure; severe anaemia can produce a hyperdynamic circulation. An isolated atrial septal defect does not classically cause wide pulse pressure. **Why the others are wrong:** (a) PDA: classically causes bounding pulses and wide pulse pressure. (b) Anaemia: may cause a hyperdynamic circulation with widened pulse pressure. (c) AR: causes high systolic and low diastolic pressure. (d) ASD: correct exception.\n\nCurriculum alignment: CVS 2024: congenital heart disease and haemodynamic findings. **High-yield point / Review Notes:** A wide pulse pressure is not specific to one lesion; interpret with examination and echocardiography.\n\nHigh-yield point: Wide pulse pressure occurs when systolic pressure is relatively high and/or diastolic pressure is low.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q68 — Cardiology / pulse pressure","aoSource":"Question-bank MD p.159 · printed p.309 · answer-key PDF p.168 · original Q68","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q72","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Cardiology / sinus bradycardia","q":"Thepathologicalcausesofthesinusbradycardia, except","o":["Raisedintracranialtension","Jaundice","Myxoedema","pheochromocytoma"],"ol":["A","B","C","D"],"k":3,"ex":"Raised intracranial pressure and hypothyroidism can cause sinus bradycardia. Severe neonatal hyperbilirubinaemia or jaundice is sometimes listed in older paediatric teaching among associations with bradycardia, although its relevance depends on context. Phaeochromocytoma typically causes catecholamine excess with tachycardia and hypertension, not sinus bradycardia, making it the intended exception.","more":"Raised intracranial pressure and hypothyroidism can cause sinus bradycardia. Severe neonatal hyperbilirubinaemia or jaundice is sometimes listed in older paediatric teaching among associations with bradycardia, although its relevance depends on context. Phaeochromocytoma typically causes catecholamine excess with tachycardia and hypertension, not sinus bradycardia, making it the intended exception. **Why the others are wrong:** (a) Raised intracranial tension: can increase vagal tone and cause bradycardia. (b) Jaundice: older teaching association; may be seen in severe neonatal illness but is nonspecific. (c) Myxoedema: hypothyroidism commonly causes bradycardia. (d) Phaeochromocytoma: usually causes tachycardia; correct exception.\n\nCurriculum alignment: CVS 2024: rhythm disturbances; CNS 2024: raised intracranial pressure; Endocrine 2025: hypothyroidism. **High-yield point / Review Notes:** Consider medications, hypoxia, athletic conditioning, conduction disease, and vagal causes when assessing bradycardia.\n\nHigh-yield point: Raised intracranial pressure and hypothyroidism can cause sinus bradycardia.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q72 — Cardiology / sinus bradycardia","aoSource":"Question-bank MD p.159 · printed p.309 · answer-key PDF p.168 · original Q72","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q75","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Cardiology / pulse examination","q":"Thepulsusalternans","o":["Rightventricularfailure","Alternatesmallandlargevolumepulse","Both","None"],"ol":["A","B","C","D"],"k":1,"ex":"Pulsus alternans is a regular rhythm with alternating strong and weak pulse amplitudes, classically associated with severe left ventricular systolic dysfunction.","more":"Pulsus alternans is a regular rhythm with alternating strong and weak pulse amplitudes, classically associated with severe left ventricular systolic dysfunction. **Why the others are wrong:** (a) Right ventricular failure: not the defining association. (b) Alternating small and large volume pulse: correct definition. (c) Both: incorrect because the pulse description in b is the definition and RV failure is not the classic cause. (d) None: incorrect.\n\nCurriculum alignment: CVS 2024: pulse examination and signs of ventricular dysfunction. **High-yield point / Review Notes:** Differentiate pulsus alternans from bigeminy (alternating electrical beats) and pulsus paradoxus (inspiratory fall in systolic pressure).\n\nHigh-yield point: Pulsus alternans is a regular rhythm with alternating strong and weak pulse amplitudes, classically associated with severe left ventricular systolic dysfunction.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q75 — Cardiology / pulse examination","aoSource":"Question-bank MD p.159 · printed p.309 · answer-key PDF p.168 · original Q75","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q82","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Cardiology / pulsus paradoxus","q":"Pulsus paradoxus is decrease in pulse volume during","o":["Inspiration","Expiration","Both","None"],"ol":["A","B","C","D"],"k":0,"ex":"Pulsus paradoxus is an exaggerated inspiratory decline in systolic arterial pressure, conventionally more than 10 mmHg. The pulse becomes weaker during inspiration because increased right ventricular filling shifts the interventricular septum leftward and reduces left ventricular filling in settings of constrained cardiac filling.","more":"Pulsus paradoxus is an exaggerated inspiratory decline in systolic arterial pressure, conventionally more than 10 mmHg. The pulse becomes weaker during inspiration because increased right ventricular filling shifts the interventricular septum leftward and reduces left ventricular filling in settings of constrained cardiac filling. **Why the others are wrong:** (a) Inspiration: correct. (b) Expiration: not the characteristic phase. (c) Both: incorrect. (d) None: incorrect.\n\nCurriculum alignment: CVS 2024: pericardial disease and cardiovascular examination. **High-yield point / Review Notes:** Classically associated with cardiac tamponade; it can also occur in severe asthma and other conditions.\n\nHigh-yield point: Pulsus paradoxus is an exaggerated inspiratory decline in systolic arterial pressure, conventionally more than 10 mmHg.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q82 — Cardiology / pulsus paradoxus","aoSource":"Question-bank MD p.160 · printed p.310 · answer-key PDF p.169 · original Q82","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q168","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Cardiology / cyanotic congenital heart disease","q":"Centralcyanosiswithenlargedleftventricle-the diagnosisis","o":["Tricuspidatresia","TetralogyofFallot","Eiesenmenger'ssyndrome","Totalanomalouspulmonaryartery"],"ol":["A","B","C","D"],"k":0,"ex":"Tricuspid atresia causes absent right atrioventricular connection and a hypoplastic right ventricle. Systemic venous blood crosses an atrial communication, and pulmonary blood flow depends on associated ventricular septal defect/patent ductus. The left ventricle may be enlarged because it supports systemic output and may handle increased volume. Central cyanosis with a relatively enlarged left ventricle is a classic clue toward tricuspid atresia among the listed options.","more":"Tricuspid atresia causes absent right atrioventricular connection and a hypoplastic right ventricle. Systemic venous blood crosses an atrial communication, and pulmonary blood flow depends on associated ventricular septal defect/patent ductus. The left ventricle may be enlarged because it supports systemic output and may handle increased volume. Central cyanosis with a relatively enlarged left ventricle is a classic clue toward tricuspid atresia among the listed options. **Why the others are wrong:** (a) Tricuspid atresia: correct classic association. (b) Tetralogy of Fallot: typically has right ventricular outflow obstruction and right ventricular hypertrophy, not the characteristic enlarged LV clue. (c) Eisenmenger syndrome: develops from longstanding pulmonary vascular disease and shunt reversal; ventricular size is not specific. (d) Total anomalous pulmonary venous connection: can cause cyanosis and right-sided volume loading, not the classic enlarged-LV association.\n\nCurriculum alignment: CVS 2024: tricuspid atresia and cyanotic congenital heart disease. **High-yield point / Review Notes:** Echocardiography confirms anatomy; the bedside clue should never replace imaging.\n\nHigh-yield point: Tricuspid atresia causes absent right atrioventricular connection and a hypoplastic right ventricle.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q168 — Cardiology / cyanotic congenital heart disease","aoSource":"Question-bank MD p.166 · printed p.316 · answer-key PDF p.169 · original Q168","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q190","spec":"eb-cardio","topic":0,"tag":"Egyptian book","kind":"Cardiology / clinical signs of heart failure","q":"Excessive sweating in young infant may be manifestation","o":["Polycythemia","Heartfailure","Phenyketonuria","Anxiety"],"ol":["A","B","C","D"],"k":1,"ex":"Infants with heart failure may sweat excessively, particularly during feeding, because feeding increases metabolic demand and cardiac workload. Associated findings may include tachypnoea, poor feeding, prolonged feeds, poor weight gain and hepatomegaly.","more":"Infants with heart failure may sweat excessively, particularly during feeding, because feeding increases metabolic demand and cardiac workload. Associated findings may include tachypnoea, poor feeding, prolonged feeds, poor weight gain and hepatomegaly. **Why the others are wrong:** (a) Polycythaemia: not the classic explanation for feeding-associated sweating. (b) Heart failure: correct. (c) Phenylketonuria: not the typical cause of this symptom. (d) Anxiety: not the expected explanation in a young infant.\n\nCurriculum alignment: CVS 2024: paediatric heart failure symptoms and signs in infants. **High-yield point / Review Notes:** Sweating with feeds plus tachypnoea and poor weight gain should prompt assessment for congenital heart disease.\n\nHigh-yield point: Infants with heart failure may sweat excessively, particularly during feeding, because feeding increases metabolic demand and cardiac workload.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q190 — Cardiology / clinical signs of heart failure","aoSource":"Question-bank MD p.167 · printed p.317 · answer-key PDF p.169 · original Q190","aoSystem":"أمراض القلب","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true}]);
